class Solution {
public:
    int maximumBags(std::vector<int>& capacity, std::vector<int>& rocks, int additionalRocks) {
        int n = capacity.size();
        std::vector<int> diff(n);
        for (int i = 0; i < n; ++i) diff[i] = capacity[i] - rocks[i];
        std::sort(diff.begin(), diff.end());
        int ans = 0;
        for (int d : diff) {
            if (additionalRocks >= d) {
                additionalRocks -= d;
                ans++;
            } else {
                break;
            }
        }
        return ans;
    }
};

class Solution {
    public int maximumBags(int[] capacity, int[] rocks, int additionalRocks) {
        int n = capacity.length;
        int[] diff = new int[n];
        for (int i = 0; i < n; i++) diff[i] = capacity[i] - rocks[i];
        java.util.Arrays.sort(diff);
        int ans = 0;
        for (int d : diff) {
            if (additionalRocks >= d) {
                additionalRocks -= d;
                ans++;
            } else {
                break;
            }
        }
        return ans;
    }
}

var maximumBags = function(capacity, rocks, additionalRocks) {
    const n = capacity.length;
    const diff = new Int32Array(n);
    for (let i = 0; i < n; i++) diff[i] = capacity[i] - rocks[i];
    diff.sort();
    let ans = 0;
    for (let i = 0; i < n; i++) {
        if (additionalRocks >= diff[i]) {
            additionalRocks -= diff[i];
            ans++;
        } else {
            break;
        }
    }
    return ans;
};
